INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(10801, '2 Chronicles 18:20', '2 Chronicles', 18, 20, '&nbsp;نو په دې کښې يو روح وروړاندې شو او مالِک خُدائ ته ورنزدې شو او وې وئيل چې زۀ به هغه دوکه کړم. او مالِک خُدائ ترې نه تپوس وکړو چې څنګه؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10802, '2 Chronicles 18:21', '2 Chronicles', 18, 21, '&nbsp;هغه روح ورته ووئيل چې زۀ به لاړ شم او د اخى‌اب په ټولو پېغمبرانو به دروغ ووايم. مالِک خُدائ وفرمائيل چې لاړ شه او هغه دوکه کړه. تۀ به کامياب شې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10803, '2 Chronicles 18:22', '2 Chronicles', 18, 22, '&nbsp;او ميکاياه په آخر کښې دا وفرمائيل چې، ”مالِک خُدائ ستا پېغمبران مجبور کړى دى چې دروغ ووائى. خو هغۀ په خپله دا اِعلان کړے دے چې په تا باندې به يو افت راشى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10804, '2 Chronicles 18:23', '2 Chronicles', 18, 23, '&nbsp;بيا صدقياه پېغمبر ميکاياه له ورَغلو، هغۀ له يې په مخ څپېړه ورکړه او تپوس يې ترې نه وکړو، ”د کوم وخت نه د مالِک خُدائ روح زما نه تلے دے او تا سره خبرې کوى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10805, '2 Chronicles 18:24', '2 Chronicles', 18, 24, '&nbsp;ميکاياه ورته وفرمائيل، ”تا ته به هغه وخت پته ولګى چې کله تۀ شا ته په يوه کوټه کښې پټ شې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10806, '2 Chronicles 18:25', '2 Chronicles', 18, 25, '&nbsp;بيا اخى‌اب بادشاه خپل يو آفسر له حُکم ورکړو، ”ميکاياه ونيسه او د ښار حاکِم امون او يوآس شهزاده له يې بوځه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10807, '2 Chronicles 18:26', '2 Chronicles', 18, 26, '&nbsp;او هغوئ ته ووايه چې هغه په قېدخانه کښې واچوى او چې ترڅو پورې زۀ په خېر سره راغلے نۀ يم نو چې هغۀ له د اوبو او روټۍ نه بغېر هيڅ ورنۀ کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10808, '2 Chronicles 18:27', '2 Chronicles', 18, 27, '&nbsp;ميکاياه په اوچت آواز سره وفرمائيل، ”کۀ تۀ په خېر سره واپس راغلې، نو بيا به مالِک خُدائ زما په ذريعه کلام نۀ وى کړے.“ او هغۀ دا هم وفرمائيل، ”ما چې څۀ وئيلى دى ټول هغه واورئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10809, '2 Chronicles 18:28', '2 Chronicles', 18, 28, '&nbsp;بيا د اِسرائيل بادشاه اخى‌اب او د يهوداه بادشاه يهوسفط په رامات‌جِلعاد ښار باندې د حملې دپاره لاړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10810, '2 Chronicles 18:29', '2 Chronicles', 18, 29, '&nbsp;اخى‌اب يهوسفط ته ووئيل، ”کله چې مونږ جنګ له لاړ شُو، نو زۀ به خپل شکل بدل کړم، خو تۀ خپل شاهى لِباس واغونده.“ نو د اِسرائيل بادشاه جنګ له لاړو او خپل شکل يې بدل کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10811, '2 Chronicles 18:30', '2 Chronicles', 18, 30, '&nbsp;د شام بادشاه د خپلو جنګى ګاډو مشرانو له حُکم ورکړے وو چې د اِسرائيل د بادشاه نه بغېر په هيچا باندې حمله ونۀ کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10812, '2 Chronicles 18:31', '2 Chronicles', 18, 31, '&nbsp;نو کله چې هغوئ يهوسفط بادشاه وليدو، نو د هغوئ ټولو خيال دا وو چې ګنې هغه د اِسرائيل بادشاه وو او هغوئ په هغۀ باندې د حملې کولو دپاره ورغلل. خو يهوسفط يوه چغه ووهله او مالِک خُدائ، خُدائ پاک هغه بچ کړو او د هغۀ نه يې حمله بل خوا کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10813, '2 Chronicles 18:32', '2 Chronicles', 18, 32, '&nbsp;د جنګى ګاډو مشرانو ته پته ولګېده چې هغه د اِسرائيل بادشاه نۀ وو، نو هغوئ په هغۀ پسې نور لا نۀ ړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10814, '2 Chronicles 18:33', '2 Chronicles', 18, 33, '&nbsp;خو يو شامى فوجى يو غشے د اِسرائيل په لښکر ورګزار کړو او اتفاقاً اخى‌اب بادشاه د هغۀ د زغرې د جوړ په مينځ باندې ولګېدو. نو هغۀ د خپلې جنګى ګاډۍ چلوونکى ته آواز وکړو، ”زۀ زخمى شوم، واپس شه او د جنګ نه ووځه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10815, '2 Chronicles 18:34', '2 Chronicles', 18, 34, '&nbsp;کله چې جنګ سخت وو، نو اخى‌اب بادشاه په خپله جنګى ګاډۍ کښې ايسار وو او تکيه يې وهلې وه او شاميانو ته يې مخ وو. نو په ماښام کښې هغه مړ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10816, '2 Chronicles 19:1', '2 Chronicles', 19, 1, '&nbsp;د يهوداه، يهوسفط بادشاه په يروشلم کښې په خېر سره خپل محل ته واپس راغلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10817, '2 Chronicles 19:2', '2 Chronicles', 19, 2, '&nbsp;د حنانى زوئ ياهُو پېغمبر د بادشاه سره مِلاوېدو له ورَغلو او ورته يې وفرمائيل، ”ستا په خيال کښې دا صحيح خبره ده چې د هغه خلقو مدد وکړے شى چې کوم بدعمله دى او د هغه خلقو طرفدارى وکړے شى چې څوک د مالِک خُدائ نه نفرت کوى؟ تا چې څۀ کړى دى د هغې په وجه تا په خپل ځان باندې د مالِک خُدائ غصه راپارولې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10818, '2 Chronicles 19:3', '2 Chronicles', 19, 3, '&nbsp;خو بيا هم، په تا کښې څۀ خوبۍ هم شته دے. تا د اشيرې بُت ټولې نښې ورانې کړې چې خلقو د هغې عبادت کولو او تا د خُدائ پاک د طلب کلکه اراده کړې وه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10819, '2 Chronicles 19:4', '2 Chronicles', 19, 4, '&nbsp;اګر چې يهوسفط په يروشلم کښې اوسېدو، هغۀ به هر وخت په جنوب کښې د بيرسبع نه واخله په شمال کښې د غرونو مُلک اِفرائيم تر غاړې پورې سفر کولو، دا د دې دپاره چې خلق مالِک خُدائ د هغوئ پلار نيکۀ خُدائ پاک ته واپس راوغواړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10820, '2 Chronicles 19:5', '2 Chronicles', 19, 5, '&nbsp;هغۀ د يهوداه د پَخو دېوالونو په هر يو ښار کښې قاضيان مقرر کړل', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10821, '2 Chronicles 19:6', '2 Chronicles', 19, 6, '&nbsp;او هغوئ ته يې دا اصُول وښودل، ”په فېصلو کولو کښې د احتياط نه کار اخلئ، تاسو به د خلقو د خوښې په مطابق فېصلې نۀ کوئ، بلکې د مالِک خُدائ په مرضۍ به کار کوئ او چې کله تاسو يوه فېصله کوئ نو مالِک خُدائ به ستاسو مل وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10822, '2 Chronicles 19:7', '2 Chronicles', 19, 7, '&nbsp;د مالِک خُدائ نه په يره کښې اوسئ او په فېصلو کولو کښې د احتياط نه کار اخلئ، ځکه چې د مالِک خُدائ زمونږ د خُدائ پاک سره نۀ بې‌اِنصافى شته، نۀ طرفدارے او نۀ رشوت.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10823, '2 Chronicles 19:8', '2 Chronicles', 19, 8, '&nbsp;يهوسفط په يروشلم کښې ليويان، اِمامان او د ښار څۀ مشران اوسېدونکى قاضيان مقرر کړل، چې د مالِک خُدائ دپاره فېصلې کوى، او د يروشلم د اوسېدونکو لانجې هواروى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10824, '2 Chronicles 19:9', '2 Chronicles', 19, 9, '&nbsp;هغۀ هغوئ ته دا اصُول وښودل، ”تاسو به خپلې ذمه وارۍ خامخا د مالِک خُدائ په يره کښې او په وفادارۍ او د زړۀ د اخلاصه ادا کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10825, '2 Chronicles 19:10', '2 Chronicles', 19, 10, '&nbsp;کله هم چې ستاسو د ښارونو نه د يو ښار اوسېدونکى ستاسو په وړاندې د قتل، يا د بل څۀ قانون يا حُکم ماتولو لانجه راوړى، نو تاسو خامخا په احتياط سره دا اصُول ورته ښايئ چې هغه به په عدالت کښې څنګه سلوک کوى، نو چې داسې هغوئ د مالِک خُدائ ګناهګار نۀ شى. کۀ تاسو داسې ونۀ کړئ، نو تاسو او ستاسو د ښارونو اوسېدونکو ته به د مالِک خُدائ د غصې پته ولګى. خو کۀ تاسو خپله ذمه وارى پوره کوئ نو تاسو به ګناهګار نۀ شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10826, '2 Chronicles 19:11', '2 Chronicles', 19, 11, '&nbsp;د ټولو مذهبى لانجو آخرى اختيار به د مشر اِمام امرياه سره وى او د خلقو په مينځ کښې د ټولو لانجو آخرى اختيار به د يهوداه د حکمران د اِسمٰعيل زوئ زبدياه سره وى. د ليويانو ذمه وارى د هغه فېصلو کتل دى کومې چې په عدالتونو کښې کيږى. تکړه شئ او په دې اصُولو عمل کوئ. او مالِک خُدائ دې د اِنصاف کوونکو سره وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10827, '2 Chronicles 20:1', '2 Chronicles', 20, 1, '&nbsp;څۀ موده وروستو د موآب او عمون فوجيان او معونيان راغلل چې د يهوسفط سره جنګ وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10828, '2 Chronicles 20:2', '2 Chronicles', 20, 2, '&nbsp;څۀ سړى راغلل او يهوسفط بادشاه ته يې ووئيل، ”د مړ درياب په بل طرف باندې د ادوم نه يو لوئ لښکر د دې دپاره راغلے دے چې په تا باندې حمله وکړى. وګورئ چې هغوئ حصيصون تامار ته رارسېدلى دى.“ (دا د عين‌جدى يو بل نوم دے).', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10829, '2 Chronicles 20:3', '2 Chronicles', 20, 3, '&nbsp;يهوسفط ويرېدو او د مالِک خُدائ د مرضۍ معلومولو دپاره يې دُعا وغوښته او په يهوداه کښې يې ټولو خلقو ته د روژې د نيولو اعلان وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10830, '2 Chronicles 20:4', '2 Chronicles', 20, 4, '&nbsp;د يهوداه خلق په يروشلم کښې د مالِک خُدائ نه د مدد غوښتلو دپاره راغونډ شول، هغوئ د مالِک خُدائ مرضى معلومولو دپاره د يهوداه د هر ښار نه راغلل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10831, '2 Chronicles 20:5', '2 Chronicles', 20, 5, '&nbsp;بيا يهوسفط د مالِک خُدائ د کور د نوى دربار په مخکښې د يهوداه او يروشلم خلقو په مينځ کښې ودرېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10832, '2 Chronicles 20:6', '2 Chronicles', 20, 6, '&nbsp;او هغۀ په اوچت آواز دُعا وکړه، ”اے مالِکه خُدايه، زمونږ د پلار نيکۀ خُدائ پاکه، تۀ په آسمان کښې د دُنيا په ټولو قومونو باندې بادشاهى کوې. ستا په لاس کښې طاقت او قوت شته او هيڅ څوک ستا مخالفت نۀ شى کولے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10833, '2 Chronicles 20:7', '2 Chronicles', 20, 7, '&nbsp;تۀ زمونږ خُدائ پاک يې. کله چې ستا خلق بنى اِسرائيليان دې مُلک ته راننوتل، چې کوم خلق دلته اوسېدل نو هغه دې وشړل او د خپل خليل اِبراهيم اولاد له دې هغه مُلک ورکړو چې د همېشه دپاره د هغوئ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10834, '2 Chronicles 20:8', '2 Chronicles', 20, 8, '&nbsp;هغوئ دلته اوسېدلى دى او ستا د نوم دپاره يې يو مقدس ځائ جوړ کړے دے او وئيل يې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10835, '2 Chronicles 20:9', '2 Chronicles', 20, 9, '&nbsp;کۀ په مونږ باندې د سزا دپاره څۀ افت، جنګ، وبا، يا قحط راشى، نو مونږ به راشو او ستا په حضور کښې به د دې کور په وړاندې ودرېږو، ځکه چې په دې کور کښې ستا نوم دے او چې په خپل مصيبت کښې مونږ تا ته سوال وکړُو نو تۀ به زمونږ سوال قبول کړې او مونږ به بچ کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10836, '2 Chronicles 20:10', '2 Chronicles', 20, 10, '&nbsp;اوس د عمون، موآب او ادوم خلقو په مونږ باندې حمله کړې ده. کله چې زمونږ پلار نيکۀ د مِصر نه راووتل، نو تا هغوئ له اجازت ورنۀ کړو چې دې مُلکونو ته ورننه وځى، نو زمونږ پلار نيکۀ د دې نه په بله لار لاړل او دا يې تباه نۀ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10837, '2 Chronicles 20:11', '2 Chronicles', 20, 11, '&nbsp;نو اوس هغوئ مونږ له د دې داسې بدله راکوى، چې راشى او مونږ د هغه مُلک نه وشړى چې تا مونږ له راکړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10838, '2 Chronicles 20:12', '2 Chronicles', 20, 12, '&nbsp;تۀ زمونږ خُدائ پاک يې. تۀ هغوئ له سزا ورکړه، ځکه چې کوم لوئ لښکر په مونږ حمله کوى نو د هغوئ په وړاندې مونږ بې‌مددګاره يُو. مونږ ته پته نشته چې څۀ وکړُو، خو مونږ ستا د مدد په طمع يُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10839, '2 Chronicles 20:13', '2 Chronicles', 20, 13, '&nbsp;د يهوداه ټول سړى، سره د خپلو ښځو او بچو، د مالِک خُدائ په حضور کښې ولاړ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10840, '2 Chronicles 20:14', '2 Chronicles', 20, 14, '&nbsp;بيا د مالِک خُدائ روح په يو ليوى نازل شو کوم چې په ګڼه کښې موجود وو. د هغۀ نوم يحزى‌ايل وو چې د زکرياه زوئ وو، هغه د آسف د قبيلې يو کس وو او د متنياه، يعى‌ايل او بناياه په ذريعه د آسف د اولاد نه وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10841, '2 Chronicles 20:15', '2 Chronicles', 20, 15, '&nbsp;يحزى‌ايل ووئيل، ”د يهوداه او يروشلم ټولو خلقو او يهوسفط بادشاه ما ته غوږ ونيسئ، مالِک خُدائ تاسو ته فرمائى چې تاسو بېخى د دې لوئ لښکر سره په مخامخ کېدو کښې مۀ يرېږئ او مۀ بې‌حوصلې کېږئ. ځکه چې دا جنګ ستاسو نۀ بلکې د خُدائ پاک دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10842, '2 Chronicles 20:16', '2 Chronicles', 20, 16, '&nbsp;سبا چې کله هغوئ د صيص درې ته راشى نو په هغوئ حمله وکړه. تۀ به د هغوئ سره د هغه وادۍ په سر کښې مِلاو شې کوم چې د يروئيل سره نزدې د ځنګل مُلک ته ځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10843, '2 Chronicles 20:17', '2 Chronicles', 20, 17, '&nbsp;تاسو به دا جنګ نۀ کوئ. صِرف د جنګ دپاره صفونه جوړ کړئ او کلک ودرېږئ، تاسو به هغه فتح ووينئ کومه چې مالِک خُدائ درکوى. مۀ يرېږئ او مۀ بې‌حوصلې کېږئ. سبا د هغوئ خِلاف راوځئ او مالِک خُدائ به ستاسو مل وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10844, '2 Chronicles 20:18', '2 Chronicles', 20, 18, '&nbsp;بيا يهوسفط بادشاه ټيټ شو او په زمکه يې سجده ولګوله او ټول خلق هم د هغۀ سره ټيټ شول او د مالِک خُدائ عبادت يې وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10845, '2 Chronicles 20:19', '2 Chronicles', 20, 19, '&nbsp;د ليويانو د قُهات او قورح د ډلو کسان پاڅېدل او په اوچت آواز يې د مالِک خُدائ د بنى اِسرائيلو د خُدائ پاک ثناء صِفت وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10846, '2 Chronicles 20:20', '2 Chronicles', 20, 20, '&nbsp;په ورپسې سحر وختى خلق د تقوع سره نزدې د ځنګل مُلک ته لاړل. چې کله هغوئ سفر شروع کړو، نو يهوسفط هغوئ ته په تقرير کښې دا خبرې وکړې، ”د يهوداه او يروشلم خلقو. په مالِک خُدائ ستاسو په خُدائ پاک باندې يقين کوئ، نو تاسو به کلک ولاړ يئ. په هغه څۀ باندې ايمان لرئ چې څۀ درته پېغمبران فرمائى، نو تاسو به کامياب شئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10847, '2 Chronicles 20:21', '2 Chronicles', 20, 21, '&nbsp;د خلقو سره د مشورې کولو نه پس، بادشاه يو څو موسيقارانو له حُکم ورکړو چې هغه چُوغې واغوندى کومې چې هغوئ په خاصو وختونو کښې اغوستې او ورته يې ووئيل چې د لښکر نه مخکښې روان شئ او داسې وايئ، ”د مالِک خُدائ ثناء صِفت دې وى. د هغۀ مينه ابدى ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10848, '2 Chronicles 20:22', '2 Chronicles', 20, 22, '&nbsp;کله چې هغوئ ثناء صِفت کول شروع کړل نو مالِک خُدائ هغه حمله کوونکى فوجيان په خپلو کښې په جګړه کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10849, '2 Chronicles 20:23', '2 Chronicles', 20, 23, '&nbsp;د عمونيانو او موآبيانو لښکرې د ادوم غر د اوسېدونکو خِلاف راوګرځېدې او د هغوئ هر يو کس يې ووژلو. کله چې هغوئ د ادوم لښکر تباه کړو نو هغوئ په يو بل باندې حملې شروع کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10850, '2 Chronicles 20:24', '2 Chronicles', 20, 24, '&nbsp;کله چې د يهوداه لښکر هغه برج ته ورسېدو کوم چې په صحرا کښې وو، نو هغوئ د دشمن طرف ته وکتل او وې ليدل چې هغوئ ټول په زمکه باندې مړۀ پراتۀ وُو. يو کس هم په تښتېدو کښې کامياب نۀ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10851, '2 Chronicles 20:25', '2 Chronicles', 20, 25, '&nbsp;نو يهوسفط او د هغۀ فوجيان ورغلل چې مالِ غنيمت راواخلى او هغوئ ډېر سامانونه، جامې او نور قيمتى څيزونه وموندل. هغوئ په مالِ غنيمت راغونډولو باندې درې ورځې تېرې کړې، خو مالِ غنيمت دومره ډېر وو چې هغوئ ټول نۀ شو راټولولے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10852, '2 Chronicles 20:26', '2 Chronicles', 20, 26, '&nbsp;په څلورمه ورځ هغوئ د براکه په وادۍ کښې راغونډ شول او د هغه هر څۀ دپاره يې د مالِک خُدائ ثناء صِفت وکړو چې څۀ هغۀ کړى وُو. نو په دې وجه د هغه وادۍ نوم ”براکه“ دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10853, '2 Chronicles 20:27', '2 Chronicles', 20, 27, '&nbsp;يهوسفط په خوشحالۍ سره فوجيان واپس يروشلم ته روان کړل، ځکه چې مالِک خُدائ د هغوئ دشمنانو له شکست ورکړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10854, '2 Chronicles 20:28', '2 Chronicles', 20, 28, '&nbsp;کله چې هغوئ ښار ته ورسېدل، نو هغوئ د ربابونو او بيګلو د غږېدو سره د مالِک خُدائ کور ته روان شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10855, '2 Chronicles 20:29', '2 Chronicles', 20, 29, '&nbsp;هر يو قوم به چې دا واورېدل چې مالِک خُدائ څنګه د اِسرائيلو دشمنانو له شکست ورکړے دے نو هغوئ به ويرېدل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10856, '2 Chronicles 20:30', '2 Chronicles', 20, 30, '&nbsp;نو يهوسفط په امن سره حکومت کولو او خُدائ پاک د هغۀ په هر رنګ باندې حِفاظت کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10857, '2 Chronicles 20:31', '2 Chronicles', 20, 31, '&nbsp;يهوسفط د پينځو دېرشو کالو په عُمر کښې بادشاه جوړ شوے وو او په يروشلم باندې يې پينځويشت کاله بادشاهى کړې وه. د هغۀ مور عزوبه وه چې د سِلحى لور وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10858, '2 Chronicles 20:32', '2 Chronicles', 20, 32, '&nbsp;د هغۀ نه مخکښې د هغۀ پلار آسا په شان هغۀ هم هغه کار کولو چې کوم د مالِک خُدائ په نظر کښې ښۀ وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10859, '2 Chronicles 20:33', '2 Chronicles', 20, 33, '&nbsp;خو علاقائى عبادتخانې نۀ وې تباه شوې، او خلق په پوره توګه د خپل پلار نيکۀ خُدائ پاک ته نۀ وُو راګرځېدلى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10860, '2 Chronicles 20:34', '2 Chronicles', 20, 34, '&nbsp;نور هر څۀ چې يهوسفط کړى دى، د هغۀ د بادشاهۍ د شروع نه واخله تر آخره پورې، هر څۀ د حنانى زوئ ياهُو په تاريخ کښې ليکلے شوى دى، کوم چې د اِسرائيل د بادشاهانو د تاريخ يوه حِصه ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10861, '2 Chronicles 20:35', '2 Chronicles', 20, 35, '&nbsp;يو ځل د يهوداه بادشاه يهوسفط د اِسرائيل بادشاه اخزياه سره اِتحاد وکړو، چا چې ډېر بد عملونه وکړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10862, '2 Chronicles 20:36', '2 Chronicles', 20, 36, '&nbsp;د عصيون‌جابر د بندرګاه سره په شريکه هغوئ سمندرى جهازُونه جوړ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10863, '2 Chronicles 20:37', '2 Chronicles', 20, 37, '&nbsp;خو د مريسه د ښار د دوداواهو زوئ اِلى‌عزر يهوسفط له خبردارے ورکړو، ”تا د اخزياه سره اِتحاد کړے دے، په دې وجه چې تا څۀ جوړ کړى دى نو مالِک خُدائ به هغه تباه کړى.“ نو سمندرى جهازُونه تباه شول او هيڅکله په سمندر کښې ونۀ چلېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10864, '2 Chronicles 21:1', '2 Chronicles', 21, 1, '&nbsp;يهوسفط مړ شو او د داؤد ښار په شاهى اديره کښې ښخ شو او د هغۀ زوئ يهورام د هغۀ نه پس بادشاه جوړ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10865, '2 Chronicles 21:2', '2 Chronicles', 21, 2, '&nbsp;د يهوسفط بادشاه د زوئ يهورام شپږ وروڼه وُو، عزرياه، يحى‌ايل زکرياه، عزرياه، ميکائيل او سفطياه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10866, '2 Chronicles 21:3', '2 Chronicles', 21, 3, '&nbsp;خپل پلار هغوئ له ډېر سرۀ زر، سپين زر او قيمتى څيزونه ورکړل او هر يو يې د يهوداه د پَخو دېوالونو ښارونو مشر مقرر کړو. يهورام د ټولو مشر وو نو په دې وجه يې هغه د دې دپاره مقرر کړو چې د هغۀ نه پس بادشاه شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10867, '2 Chronicles 21:4', '2 Chronicles', 21, 4, '&nbsp;کله چې بادشاهى په پوره توګه د يهورام په لاس کښې وه، نو هغۀ خپل ټول وروڼه او د اِسرائيل څۀ مشران هم ووژل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10868, '2 Chronicles 21:5', '2 Chronicles', 21, 5, '&nbsp;يهورام د دوو دېرشو کالو په عُمر کښې بادشاه شو او اتۀ کاله يې په يروشلم حکومت وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10869, '2 Chronicles 21:6', '2 Chronicles', 21, 6, '&nbsp;هغۀ د اخى‌اب بادشاه او د اِسرائيل نورو بادشاهانو په بدو مِثالونو باندې عمل وکړو، ځکه چې هغۀ د اخى‌اب يوه لور وادۀ کړې وه. هغۀ د مالِک خُدائ خِلاف ګناه وکړه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10870, '2 Chronicles 21:7', '2 Chronicles', 21, 7, '&nbsp;خو د مالِک خُدائ دا مرضى نۀ وه چې د داؤد شاهى خاندان تباه کړى، ځکه چې هغۀ د داؤد سره لوظ کړے وو او دا وعده يې ورسره کړې وه چې د هغۀ اولاد به د همېشه دپاره بادشاهى کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10871, '2 Chronicles 21:8', '2 Chronicles', 21, 8, '&nbsp;د يهورام د بادشاهۍ په وخت کښې ادوم د يهوداه خِلاف بغاوت وکړو او يو خپل بادشاه يې مقرر کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10872, '2 Chronicles 21:9', '2 Chronicles', 21, 9, '&nbsp;نو يهورام او د هغۀ آفسرانو خپلې ټولې جنګى ګاډۍ او لښکرې روانې کړې او د ادوميانو نه شپه په شپه راتاو شو او په هغوئ يې سخته حمله وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10873, '2 Chronicles 21:10', '2 Chronicles', 21, 10, '&nbsp;نو ادوم تر نن پورې د يهوداه نه آزاد دے. هم په هغه وخت کښې د لِبناه ښار هم بغاوت وکړو، دا هر څۀ ځکه وشول چې يهورام مالِک خُدائ د خپل پلار نيکۀ خُدائ پاک پرېښے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10874, '2 Chronicles 21:11', '2 Chronicles', 21, 11, '&nbsp;هغۀ د يهوداه په غريزه علاقه کښې علاقائى عبادتخانه جوړه کړې وه او د يهوداه او د يروشلم خلق يې بې‌لارې کړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10875, '2 Chronicles 21:12', '2 Chronicles', 21, 12, '&nbsp;الياس پېغمبر يهورام له يو خط ولېږلو، چې په هغې کښې ليکلى شوى وُو، ”مالِک خُدائ، ستا د پلار نيکۀ داؤد خُدائ پاک تا رد کوى، ځکه چې تا د خپل پلار يهوسفط بادشاه او د خپل نيکۀ آسا په نقش قدم مزل نۀ دے کړے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10876, '2 Chronicles 21:13', '2 Chronicles', 21, 13, '&nbsp;تا د اِسرائيل د بادشاهانو په نقش قدم باندې مزل کړے دے او د يهوداه او يروشلم په خلقو دې د بُتانو عبادت کړے دے، لکه څنګه چې اخى‌اب او د اِسرائيل نورو بادشاهانو کړى وُو. تا خو خپل وروڼه هم ووژل، چې هغوئ ستا نه ښۀ سړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10877, '2 Chronicles 21:14', '2 Chronicles', 21, 14, '&nbsp;نو اوس به مالِک خُدائ ستا خلقو له، ستا بچو او ستا ښځو له سخته سزا ورکړى او ستا هر څۀ به تباه کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10878, '2 Chronicles 21:15', '2 Chronicles', 21, 15, '&nbsp;تۀ به د کولمو په سخت مرض باندې آخته شې چې هغه به ورځ په ورځ زياتيږى تر دې پورې چې کولمې به درنه بهر راوځى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10879, '2 Chronicles 21:16', '2 Chronicles', 21, 16, '&nbsp;څۀ فلستيان او عرب د هغه ځائ سره نزدې اوسېدل چرته چې څۀ د ايتهوپيا خلق د سيند په غاړه دېره وُو. مالِک خُدائ هغوئ ولمسول چې د يهورام خِلاف جنګ له لاړ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10880, '2 Chronicles 21:17', '2 Chronicles', 21, 17, '&nbsp;هغوئ په يهوداه حمله وکړه، شاهى محل يې لوټ کړو او د بادشاه د کشرى زوئ، اخزياه نه بغېر يې د بادشاه ټولې ښځې او زامن قېديان بوتلل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10881, '2 Chronicles 21:18', '2 Chronicles', 21, 18, '&nbsp;بيا د دې هر څۀ نه پس، مالِک خُدائ په بادشاه باندې د کولمو سخت مرض راوستلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10882, '2 Chronicles 21:19', '2 Chronicles', 21, 19, '&nbsp;تقريباً دوه کاله دا مرض په مزه مزه زياتېدو تر دې پورې چې د هغۀ کولمې بهر راووتې او هغه په يو سخت تکليف کښې مړ شو. د هغۀ خلقو د هغۀ د عزت دپاره اور بل نۀ کړو لکه چې د هغۀ د پلار نيکۀ دپاره بل شوے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10883, '2 Chronicles 21:20', '2 Chronicles', 21, 20, '&nbsp;يهورام د دوو دېرشو کالو په عُمر کښې بادشاه جوړ شوے وو او اتۀ کاله يې په يروشلم بادشاهى کړې وه. کله چې هغه مړ شو نو هيڅ څوک هم خفه نۀ وُو. هغوئ هغه د داؤد په ښار کښې ښخ کړو، خو په شاهى اديره کښې يې ښخ نۀ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10884, '2 Chronicles 22:1', '2 Chronicles', 22, 1, '&nbsp;څۀ عربو حمله وکړه او د يهورام بادشاه د کشرى زوئ اخزياه نه بغېر يې د يهورام ټول زامن ووژل. نو بيا د يروشلم خلقو اخزياه د خپل پلار نه پس بادشاه جوړ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10885, '2 Chronicles 22:2', '2 Chronicles', 22, 2, '&nbsp;اخزياه د دوويشتو کالو په عُمر کښې بادشاه جوړ شو او يو کال يې په يروشلم باندې بادشاهى وکړه. د هغۀ مور عتلياه وه چې د عُمرى بادشاه نمسۍ وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10886, '2 Chronicles 22:3', '2 Chronicles', 22, 3, '&nbsp;اخزياه د اخى‌اب د خاندان په نقش قدم باندې روان وو، ځکه چې د هغۀ مور عتلياه هغۀ ته بدې لارې ښودلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10887, '2 Chronicles 22:4', '2 Chronicles', 22, 4, '&nbsp;هغۀ د مالِک خُدائ خِلاف ګناه وکړه، ځکه چې د هغۀ د پلار د مرګ نه پس د اخى‌اب د خاندان نور کسان د هغۀ مشيران شول او هغه يې د تباهۍ طرف ته بوتلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10888, '2 Chronicles 22:5', '2 Chronicles', 22, 5, '&nbsp;د هغوئ په مشورو يې عمل کولو کله چې د شام بادشاه حِزائيل خِلاف يې په يو جنګ کښې د اِسرائيل د بادشاه يورام ملګرتيا وکړه. لښکرې په رامات‌جِلعاد کښې په جنګ شوې او يورام په جنګ کښې زخمى شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10889, '2 Chronicles 22:6', '2 Chronicles', 22, 6, '&nbsp;هغه د يزرعيل ښار ته ځکه راواپس شو چې د هغۀ زخمونه روغ شى او اخزياه هلته د مِلاوېدو دپاره ورَغلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10890, '2 Chronicles 22:7', '2 Chronicles', 22, 7, '&nbsp;خُدائ پاک د يورام دا ملاقات د اخزياه د تباهۍ سبب وګرځولو. هغه او يورام، ياهُو زوئ د نِمسى سره مِلاوېدو دپاره راوتل، کوم چې مالِک خُدائ د اخى‌اب شاهى خاندان د تباه کولو دپاره خوښ کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10891, '2 Chronicles 22:8', '2 Chronicles', 22, 8, '&nbsp;کله چې ياهُو د اخى‌اب په شاهى خاندان باندې د خُدائ پاک سزا راوستله، نو هغه د يهوداه د قبيلې يو څو مشرانو او د اخزياه خپلوانو سره مِلاو شو چې هغوئ د اخزياه سره روان وُو نو ياهُو هغوئ ټول ووژل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10892, '2 Chronicles 22:9', '2 Chronicles', 22, 9, '&nbsp;اخزياه ولټولے شو او هغه په سامريه کښې پټ وو او هلته پېدا شو. هغوئ هغه ياهُو ته بوتلو او وې وژلو. خو هغوئ د هغۀ لاش د هغۀ نيکۀ يهوسفط بادشاه د عزت په وجه ښخ کړو، ځکه يهوسفط د مالِک خُدائ د خِدمت دپاره هر څۀ کړى وُو. نو د اخزياه د خاندان داسې يو کس هم پاتې نۀ شو چې هغۀ بادشاهى کړے وے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10893, '2 Chronicles 22:10', '2 Chronicles', 22, 10, '&nbsp;څنګه چې د اخزياه بادشاه مور عتلياه د خپل زوئ د قتل نه خبر شوه، نو هغې دا حُکم ورکړو چې د يهوداه د شاهى خاندان مکمل کسان دې ووژلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10894, '2 Chronicles 22:11', '2 Chronicles', 22, 11, '&nbsp;د اخزياه يوه ناسکه خور يهوسبع وه، د هغې وادۀ د يهويدع اِمام سره شوے وو. هغې په پټه باندې د اخزياه يو زوئ يوآس بچ کړو، هغه يې د هغه نورو شهزادګانو نه يوړو کوم چې قتل کېدونکے وو او هغه او د هغۀ خِدمتګاره يې پټ کړل او د اودۀ کېدو په يوه کوټه کښې د هغوئ خيال ساتلو. نو داسې يهوسبع د هغۀ د پټ ساتلو په وجه باندې هغه د عتلياه د لاسه د مرګ نه بچ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10895, '2 Chronicles 22:12', '2 Chronicles', 22, 12, '&nbsp;تر شپږو کالو پورې هغه هلته پټ وو کله چې عتلياه د مَلِکه په توګه بادشاهى کوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10896, '2 Chronicles 23:1', '2 Chronicles', 23, 1, '&nbsp;د شپږو کالو اِنتظار نه پس يهويدع اِمام يوه فېصله وکړه. هغۀ د دې پينځو فوجى آفسرانو سره لوظ وکړو، د يروحام زوئ عزرياه، د يهوحنان زوئ اِسمٰعيل، د عوبيد زوئ عزرياه، د عداياه زوئ معسياه او د زِکرى زوئ الياسفط.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10897, '2 Chronicles 23:2', '2 Chronicles', 23, 2, '&nbsp;هغوئ د يهوداه ټولو ښارونو ته سفر وکړو او ځان سره يې واپس يروشلم ته ليويان او د ډلو ټول مشران راوستل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10898, '2 Chronicles 23:3', '2 Chronicles', 23, 3, '&nbsp;هغوئ ټول د خُدائ پاک په کور کښې راغونډ شول او هلته هغوئ د بادشاه د زوئ يوآس سره يو لوظ وکړو. يهويدع هغوئ ته ووئيل، ”د بادشاه زوئ دا دے. دے به اوس بادشاه جوړيږى، لکه څنګه چې مالِک خُدائ فرمائيلى دى چې د داؤد اولاد به بادشاهان وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10899, '2 Chronicles 23:4', '2 Chronicles', 23, 4, '&nbsp;نو مونږ به هم دغه شان کوُو. کله چې اِمامان او ليويان د سبت په ورځ د خپل کار دپاره راځى، نو د هغوئ درېمه برخه به د مالِک خُدائ د کور د دروازو څوکيدارى کوى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10900, '2 Chronicles 23:5', '2 Chronicles', 23, 5, '&nbsp;هغه بله درېمه برخه به د شاهى محل څوکيدارى کوى او باقى پاتې برخه به د ”بنياد“ په دروازه باندې مقررولے شى. ټول خلق به د مالِک خُدائ د کور په دربار کښې راغونډ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');